+            },
+            captureConsole: true,
+            onCliExecute: function (cmdOpts) {
+                var c = cmdOpts.command;
+                if (c.indexOf('/jobs?per_page=100') !== -1) {
+                    return JOBS_PAYLOAD;
+                }
+                if (opts.onCliExecute) return opts.onCliExecute(cmdOpts);
+                return undefined;
+            }
+        }));
